import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { X, ArrowRight, ArrowLeft, Check, Sparkles } from 'lucide-react';
import { getPrinterCoverUrl, getBrandMeta, getMaterialSpoolUrl, MATERIAL_DATA } from '../data/printerVisuals';

const LANGUAGES = [
  { code: 'en', label: 'English', short: 'EN' },
  { code: 'fr', label: 'Français', short: 'FR' },
  { code: 'es', label: 'Español', short: 'ES' },
  { code: 'de', label: 'Deutsch', short: 'DE' },
  { code: 'it', label: 'Italiano', short: 'IT' },
];

export default function WizardModal({
  show,
  onClose,
  printers = [],
  materials = [],
  selectedPrinterId,
  onSelectPrinter,
  selectedMaterialId,
  onSelectMaterial,
  apiKey,
  onSaveApiKey,
  isHosted
}) {
  const { t, i18n } = useTranslation();
  const [step, setStep] = useState(1);
  const [tempKey, setTempKey] = useState(apiKey || '');

  React.useEffect(() => {
    if (show) {
      setStep(1);
      setTempKey(apiKey || '');
    }
  }, [show, apiKey]);

  if (!show) return null;

  const maxSteps = isHosted ? 3 : 4;

  const handleFinish = () => {
    if (!isHosted && tempKey) {
      onSaveApiKey(tempKey);
    }
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-900/40 backdrop-blur-xs flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl border border-slate-200 w-full max-w-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-150">
        {/* Modal Top Bar */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-slate-50/50">
          <div className="flex items-center space-x-2.5">
            <span className="px-2.5 py-0.5 rounded-full text-xs font-bold bg-primary-50 text-primary-700 border border-primary-200">
              Step {step} of {maxSteps}
            </span>
            <h2 className="text-sm font-bold text-slate-900">
              {t('wizardTitle')}
            </h2>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-slate-600 rounded-lg p-1"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Modal Body */}
        <div className="p-6">
          {/* Step 1: Language */}
          {step === 1 && (
            <div>
              <h3 className="text-sm font-bold text-slate-900 mb-1">
                {t('wizardStepLang')}
              </h3>
              <p className="text-xs text-slate-500 mb-4">
                {t('wizardStepLangDesc')}
              </p>

              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2.5">
                {LANGUAGES.map((lang) => {
                  const isSelected = (i18n.language || 'en').startsWith(lang.code);
                  return (
                    <button
                      key={lang.code}
                      type="button"
                      onClick={() => {
                        i18n.changeLanguage(lang.code);
                        try {
                          localStorage.setItem('slicer_language', lang.code);
                        } catch (e) {}
                      }}
                      className={`p-3 rounded-xl border text-left flex items-center justify-between transition-all ${
                        isSelected
                          ? 'bg-primary-50/70 border-primary-500 ring-2 ring-primary-500/20'
                          : 'bg-white border-slate-200 hover:border-slate-300'
                      }`}
                    >
                      <span className="text-xs font-bold text-slate-800">{lang.label}</span>
                      <span className="text-[11px] font-mono text-slate-400 font-semibold">{lang.short}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* Step 2: Printer */}
          {step === 2 && (
            <div>
              <h3 className="text-sm font-bold text-slate-900 mb-1">
                {t('wizardStepPrinter')}
              </h3>
              <p className="text-xs text-slate-500 mb-3">
                {t('wizardStepPrinterDesc')}
              </p>

              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2.5 max-h-[320px] overflow-y-auto pr-1 custom-scrollbar">
                {printers.map((printer) => {
                  const isSelected = printer.id === selectedPrinterId;
                  const pBrand = getBrandMeta(printer.manufacturer);
                  return (
                    <button
                      key={printer.id}
                      type="button"
                      onClick={() => onSelectPrinter(printer.id)}
                      className={`p-2.5 rounded-xl border text-left transition-all flex flex-col justify-between ${
                        isSelected
                          ? 'bg-primary-50/70 border-primary-500 ring-2 ring-primary-500/20'
                          : 'bg-white border-slate-200 hover:border-slate-300'
                      }`}
                    >
                      <div className="w-full h-16 bg-slate-50 rounded-lg flex items-center justify-center p-1 mb-2 border border-slate-100 overflow-hidden">
                        <img
                          src={getPrinterCoverUrl(printer.id)}
                          alt={printer.displayName}
                          className="max-h-full max-w-full object-contain"
                          onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = `${process.env.PUBLIC_URL}/images/printers/creality_ender3.png`;
                          }}
                        />
                      </div>
                      <div>
                        <span className="text-[9px] font-bold block uppercase" style={{ color: pBrand.text }}>
                          {printer.manufacturer}
                        </span>
                        <span className="text-xs font-bold text-slate-800 block truncate" title={printer.displayName}>
                          {printer.displayName}
                        </span>
                        <span className="text-[10px] text-slate-400 font-mono block">
                          {printer.bedSize ? `${printer.bedSize[0]}×${printer.bedSize[1]}` : '220×220'} mm
                        </span>
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* Step 3: Material */}
          {step === 3 && (
            <div>
              <h3 className="text-sm font-bold text-slate-900 mb-1">
                {t('wizardStepMaterial')}
              </h3>
              <p className="text-xs text-slate-500 mb-3">
                {t('wizardStepMaterialDesc')}
              </p>

              <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
                {materials.map((mat) => {
                  const isSelected = mat.id === selectedMaterialId;
                  const meta = MATERIAL_DATA[mat.id] || MATERIAL_DATA.pla;
                  return (
                    <button
                      key={mat.id}
                      type="button"
                      onClick={() => onSelectMaterial(mat.id)}
                      className={`p-3 rounded-xl border text-center flex flex-col items-center transition-all ${
                        isSelected
                          ? 'bg-primary-50/70 border-primary-500 ring-2 ring-primary-500/20'
                          : 'bg-white border-slate-200 hover:border-slate-300'
                      }`}
                    >
                      <div className="w-12 h-12 mb-1.5">
                        <img
                          src={getMaterialSpoolUrl(mat.id)}
                          alt={meta.name}
                          className="w-full h-full object-contain"
                        />
                      </div>
                      <span className="text-xs font-bold text-slate-800 block">{mat.id.toUpperCase()}</span>
                      <span className="text-[10px] text-slate-400 block font-mono">{mat.density} g/cm³</span>
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {/* Step 4: RapidAPI Key */}
          {!isHosted && step === 4 && (
            <div>
              <h3 className="text-sm font-bold text-slate-900 mb-1">
                {t('wizardStepApiKey')}
              </h3>
              <p className="text-xs text-slate-500 mb-3">
                {t('wizardStepApiKeyDesc')}
              </p>

              <div className="p-4 rounded-xl bg-slate-50 border border-slate-200 mb-3">
                <label className="text-xs font-semibold text-slate-700 block mb-1">
                  X-RapidAPI-Key (Optional now, required at slice time)
                </label>
                <input
                  type="password"
                  className="w-full px-3 py-2 text-xs font-mono rounded-lg border border-slate-200 bg-white placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-primary-500"
                  placeholder={t('apiKeyPlaceholder')}
                  value={tempKey}
                  onChange={(e) => setTempKey(e.target.value)}
                />
                <span className="text-[11px] text-slate-500 block mt-1.5">
                  You can leave this blank now; you will simply be prompted to enter it when you calculate an estimate.
                </span>
              </div>

              <span className="text-xs font-medium text-emerald-600 block flex items-center space-x-1">
                <Check className="w-4 h-4 text-emerald-600" />
                <span>{t('wizardComplete')}</span>
              </span>
            </div>
          )}
        </div>

        {/* Modal Footer */}
        <div className="px-6 py-4 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
          <button
            type="button"
            onClick={() => setStep(Math.max(1, step - 1))}
            disabled={step === 1}
            className="inline-flex items-center space-x-1 px-3 py-1.5 rounded-lg text-xs font-semibold text-slate-600 hover:text-slate-900 disabled:opacity-40 disabled:cursor-not-allowed"
          >
            <ArrowLeft className="w-3.5 h-3.5" />
            <span>{t('back')}</span>
          </button>

          {step < maxSteps ? (
            <button
              type="button"
              onClick={() => setStep(step + 1)}
              className="inline-flex items-center space-x-1 px-4 py-1.5 rounded-lg text-xs font-semibold bg-primary-600 hover:bg-primary-700 text-white shadow-xs"
            >
              <span>{t('next')}</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </button>
          ) : (
            <button
              type="button"
              onClick={handleFinish}
              className="inline-flex items-center space-x-1 px-4 py-1.5 rounded-lg text-xs font-semibold bg-emerald-600 hover:bg-emerald-700 text-white shadow-xs"
            >
              <Sparkles className="w-3.5 h-3.5" />
              <span>{t('finish')}</span>
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
