import React from 'react';
import { useTranslation } from 'react-i18next';
import { Clock, Weight, Euro, RotateCw, CheckCircle2 } from 'lucide-react';
import { getPrinterCoverUrl, getMaterialSpoolUrl, MATERIAL_DATA } from '../data/printerVisuals';

function formatTime(seconds) {
  if (!seconds || seconds <= 0) return '0s';
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const remSec = seconds % 60;
  return `${hours > 0 ? hours + 'h ' : ''}${hours > 0 || minutes > 0 ? minutes + 'm ' : ''}${remSec}s`;
}

export default function EstimateResultCard({
  result,
  selectedPrinter,
  selectedMaterial,
  onRecalculate,
  isSimple
}) {
  const { t } = useTranslation();

  if (!result) return null;

  const grams = result.total_filament_used_g || 0;
  const timeSeconds = result.estimated_printing_time_seconds || 0;
  const directCost = result.cost && result.cost.material_cost != null ? result.cost.material_cost : null;

  // Maker estimated shop selling price
  const makerSalePrice = Math.max(
    Math.round(((grams / 1000 * 20 + 0.83 * (timeSeconds / 3600)) / (1 - 0.30)) / 5) * 5,
    2.5
  );

  const matMeta = MATERIAL_DATA[selectedMaterial] || MATERIAL_DATA.pla;

  return (
    <div className="studio-card p-4 sm:p-5 border-2 border-emerald-500/40 bg-gradient-to-b from-emerald-50/20 to-white shadow-md mb-4 animate-in fade-in zoom-in-95 duration-150">
      {/* Header */}
      <div className="flex items-center justify-between pb-3 mb-3 border-b border-emerald-100">
        <div className="flex items-center space-x-2">
          <div className="w-7 h-7 rounded-lg bg-emerald-100 text-emerald-700 flex items-center justify-center">
            <CheckCircle2 className="w-4 h-4 text-emerald-700" />
          </div>
          <div>
            <h2 className="text-sm sm:text-base font-bold text-slate-900 leading-tight">
              {t('estimateResults')}
            </h2>
            <span className="text-[11px] text-slate-500">
              Sliced using accurate OrcaSlicer toolpaths
            </span>
          </div>
        </div>

        <button
          type="button"
          onClick={onRecalculate}
          className="inline-flex items-center space-x-1 text-xs font-semibold px-2.5 py-1.5 rounded-lg border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 shadow-2xs"
        >
          <RotateCw className="w-3 h-3" />
          <span>{t('recalculate')}</span>
        </button>
      </div>

      {/* Primary Metrics Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5 mb-3">
        {/* Print Time */}
        <div className="p-3 rounded-xl bg-white border border-slate-200/90 shadow-2xs">
          <div className="flex items-center space-x-1.5 text-slate-400 mb-1">
            <Clock className="w-3.5 h-3.5 text-slate-500" />
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">
              {t('totalPrintTime')}
            </span>
          </div>
          <span className="text-xl sm:text-2xl font-extrabold font-mono text-slate-900 block">
            {formatTime(timeSeconds)}
          </span>
        </div>

        {/* Filament Used */}
        <div className="p-3 rounded-xl bg-white border border-slate-200/90 shadow-2xs">
          <div className="flex items-center space-x-1.5 text-slate-400 mb-1">
            <Weight className="w-3.5 h-3.5 text-emerald-600" />
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">
              {t('filamentUsed')}
            </span>
          </div>
          <span className="text-xl sm:text-2xl font-extrabold font-mono text-emerald-600 block">
            {grams} g
          </span>
        </div>

        {/* Price / Cost */}
        <div className="p-3 rounded-xl bg-white border border-slate-200/90 shadow-2xs">
          <div className="flex items-center space-x-1.5 text-slate-400 mb-1">
            <Euro className="w-3.5 h-3.5 text-primary-600" />
            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">
              {directCost != null ? 'Material Cost' : t('makerTotalCost')}
            </span>
          </div>
          <span className="text-xl sm:text-2xl font-extrabold font-mono text-primary-600 block">
            {directCost != null ? `${directCost.toFixed(2)} €` : `${makerSalePrice.toFixed(2)} €`}
          </span>
        </div>
      </div>

      {/* Recap Metadata */}
      <div className="p-2.5 rounded-xl bg-slate-50 border border-slate-200/80 flex items-center justify-between flex-wrap gap-2 text-xs">
        <div className="flex items-center space-x-3">
          <div className="flex items-center space-x-1.5">
            <img
              src={getPrinterCoverUrl(selectedPrinter ? selectedPrinter.id : '')}
              alt=""
              className="w-5 h-5 object-contain rounded"
            />
            <span className="font-semibold text-slate-800">
              {selectedPrinter ? selectedPrinter.displayName : 'Printer'}
            </span>
          </div>
          <span className="text-slate-300">|</span>
          <div className="flex items-center space-x-1.5">
            <img
              src={getMaterialSpoolUrl(selectedMaterial)}
              alt=""
              className="w-4 h-4 object-contain"
            />
            <span className="font-semibold text-slate-800">
              {matMeta.name} ({matMeta.density}g/cm³)
            </span>
          </div>
        </div>

        {directCost == null && (
          <span className="text-[11px] text-slate-500 italic">
            {t('makerTotalCostNotice')}
          </span>
        )}
      </div>

      {/* Simple Kofi flow */}
      {isSimple && (
        <div className="mt-3 pt-2.5 border-t border-slate-100">
          <a
            href="https://ko-fi.com/s/0aed439a68"
            target="_blank"
            rel="noreferrer"
            className="w-full py-2.5 px-4 rounded-xl font-bold text-xs bg-amber-400 hover:bg-amber-500 text-slate-900 flex items-center justify-center space-x-2 shadow-xs transition-colors"
          >
            <img src={`${process.env.PUBLIC_URL}/kofi.png`} alt="ko-fi" className="w-4 h-4 object-contain" />
            <span>{t('orderSample')}</span>
          </a>
        </div>
      )}
    </div>
  );
}
