import React from 'react';

// Layer stack visual illustration showing slicing resolution from coarse to ultra-fine
export function LayerHeightIcon({ level = 'normal', className = "w-5 h-5" }) {
  // Level: 'draft' (thick layers), 'normal' (medium layers), 'precision' (ultra-fine layers), 'auto' (default)
  if (level === 'draft') {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        {/* 3 thick layers */}
        <rect x="3" y="4" width="18" height="4.5" rx="1" fill="#94A3B8" />
        <rect x="3" y="10" width="18" height="4.5" rx="1" fill="#64748B" />
        <rect x="3" y="16" width="18" height="4.5" rx="1" fill="#475569" />
      </svg>
    );
  }

  if (level === 'precision') {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        {/* 6 fine layers */}
        <rect x="3" y="3" width="18" height="1.8" rx="0.5" fill="#94A3B8" />
        <rect x="3" y="6.5" width="18" height="1.8" rx="0.5" fill="#64748B" />
        <rect x="3" y="10" width="18" height="1.8" rx="0.5" fill="#0284C7" />
        <rect x="3" y="13.5" width="18" height="1.8" rx="0.5" fill="#0284C7" />
        <rect x="3" y="17" width="18" height="1.8" rx="0.5" fill="#475569" />
        <rect x="3" y="20.5" width="18" height="1.8" rx="0.5" fill="#334155" />
      </svg>
    );
  }

  if (level === 'normal') {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        {/* 4 standard layers */}
        <rect x="3" y="4" width="18" height="3" rx="0.75" fill="#94A3B8" />
        <rect x="3" y="8.5" width="18" height="3" rx="0.75" fill="#64748B" />
        <rect x="3" y="13" width="18" height="3" rx="0.75" fill="#0284C7" />
        <rect x="3" y="17.5" width="18" height="3" rx="0.75" fill="#475569" />
      </svg>
    );
  }

  // Default / Auto
  return (
    <svg className={className} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
      <rect x="3" y="5" width="18" height="3" rx="0.75" fill="#CBD5E1" stroke="#94A3B8" strokeWidth="0.5" />
      <rect x="3" y="10.5" width="18" height="3" rx="0.75" fill="#94A3B8" stroke="#64748B" strokeWidth="0.5" />
      <rect x="3" y="16" width="18" height="3" rx="0.75" fill="#64748B" stroke="#475569" strokeWidth="0.5" />
    </svg>
  );
}
