import axios from 'axios';
import catalogFallback from './catalogFallback.json';

const STORAGE_KEYS = {
  SETTINGS: 'slicer_user_settings_v2',
  API_KEY: 'slicer_rapidapi_key',
  WIZARD_SEEN: 'slicer_wizard_completed_v2',
  LANGUAGE: 'slicer_language'
};

// Default setup: Base selection, but NO OVERRIDES by default (empty fields so printer/backend defaults apply)
const DEFAULT_SETTINGS = {
  printerId: 'bambulab_p1s',
  materialId: 'pla',
  quality: '', // empty = backend preset default (0.20)
  layerHeight: '',
  infill: '', // empty = preset default (20%)
  support: null, // null = preset default (true)
  speed: '', // empty = preset printer speed
  acceleration: '', // empty = preset printer accel
  filamentDensity: '', // empty = preset material density
  pricePerKg: '', // optional cost calculation
  rotateX: 0,
  rotateY: 0,
  rotateZ: 0
};

export const getStoredSettings = () => {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.SETTINGS);
    if (!raw) return DEFAULT_SETTINGS;
    return { ...DEFAULT_SETTINGS, ...JSON.parse(raw) };
  } catch (e) {
    console.error('Error reading settings from localStorage', e);
    return DEFAULT_SETTINGS;
  }
};

export const saveStoredSettings = (settings) => {
  try {
    localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(settings));
  } catch (e) {
    console.error('Error saving settings to localStorage', e);
  }
};

export const getStoredApiKey = () => {
  try {
    return localStorage.getItem(STORAGE_KEYS.API_KEY) || '';
  } catch (e) {
    return '';
  }
};

export const saveStoredApiKey = (key) => {
  try {
    localStorage.setItem(STORAGE_KEYS.API_KEY, key ? key.trim() : '');
  } catch (e) {
    console.error('Error saving API key to localStorage', e);
  }
};

export const hasCompletedWizard = () => {
  try {
    return localStorage.getItem(STORAGE_KEYS.WIZARD_SEEN) === 'true';
  } catch (e) {
    return false;
  }
};

export const markWizardCompleted = () => {
  try {
    localStorage.setItem(STORAGE_KEYS.WIZARD_SEEN, 'true');
  } catch (e) {
    console.error('Error saving wizard status', e);
  }
};

const RAPIDAPI_HOST = '3d-print-stl-estimation.p.rapidapi.com';
const RAPIDAPI_BASE_URL = process.env.REACT_APP_API_BASE_URL || `https://${RAPIDAPI_HOST}`;

export const fetchPresetsCatalog = async (isHosted) => {
  // Static deployment (GitHub Pages): there is no same-origin backend to ask
  if (process.env.REACT_APP_STATIC_SITE === 'true') return catalogFallback;
  try {
    const response = await axios.get('/v1/presets', { timeout: 3000 });
    if (response.data && response.data.printers && response.data.printers.length > 0) {
      return response.data;
    }
  } catch (err) {
    // Fallback when standalone
  }
  return catalogFallback;
};

export const calculateEstimate = async (file, options, { isHosted, apiKey }) => {
  const formData = new FormData();
  formData.append('model_file', file);
  formData.append('printer', options.printerId || 'bambulab_p1s');
  formData.append('material', options.materialId || 'pla');

  // ONLY append parameters if the user explicitly provided an override!
  if (options.quality && options.quality.trim() !== '') {
    formData.append('quality', options.quality);
  }
  if (options.layerHeight && Number(options.layerHeight) > 0) {
    formData.append('layer_height', options.layerHeight);
  }
  if (options.infill !== '' && options.infill !== null && options.infill !== undefined) {
    formData.append('fill_density', options.infill);
  }
  if (options.support !== null && options.support !== undefined) {
    formData.append('support_material', options.support);
  }
  if (options.speed && Number(options.speed) > 0) {
    formData.append('speed', options.speed);
  }
  if (options.acceleration && Number(options.acceleration) > 0) {
    formData.append('acceleration', options.acceleration);
  }
  if (options.filamentDensity && Number(options.filamentDensity) > 0) {
    formData.append('filament_density', options.filamentDensity);
  }
  if (options.rotateX && Number(options.rotateX) !== 0) {
    formData.append('rotate_x', options.rotateX);
  }
  if (options.rotateY && Number(options.rotateY) !== 0) {
    formData.append('rotate_y', options.rotateY);
  }
  if (options.rotateZ && Number(options.rotateZ) !== 0) {
    formData.append('rotate_z', options.rotateZ);
  }
  if (options.pricePerKg && Number(options.pricePerKg) > 0) {
    formData.append('filament_price_per_kg', options.pricePerKg);
  }

  const endpoint = isHosted
    ? '/v1/estimates'
    : `${RAPIDAPI_BASE_URL}/v1/estimates`;

  const headers = {
    'Content-Type': 'multipart/form-data'
  };

  if (!isHosted) {
    headers['X-RapidAPI-Key'] = apiKey;
    headers['X-RapidAPI-Host'] = RAPIDAPI_HOST;
  }

  const response = await axios.post(endpoint, formData, { headers });
  return response.data;
};
