// Client-side STL geometry parsing and auto-orient optimizer
// Finds the optimal orientation that maximizes stable contact area on the print bed
// and minimizes floating overhangs (faces that do NOT touch the bed).

export const parseStlTriangles = async (file) => {
  const buffer = await file.arrayBuffer();
  const dataView = new DataView(buffer);
  const isAscii = checkIfAscii(buffer);

  if (isAscii) {
    return parseAsciiStl(new TextDecoder().decode(buffer));
  } else {
    return parseBinaryStl(dataView);
  }
};

function checkIfAscii(buffer) {
  const text = new TextDecoder('ascii').decode(buffer.slice(0, 512));
  return text.startsWith('solid') && text.includes('facet');
}

function parseBinaryStl(dataView) {
  const triangles = [];
  if (dataView.byteLength < 84) return triangles;

  const numTriangles = dataView.getUint32(80, true);
  let offset = 84;

  for (let i = 0; i < numTriangles && offset + 50 <= dataView.byteLength; i++) {
    // Normal
    const nx = dataView.getFloat32(offset, true);
    const ny = dataView.getFloat32(offset + 4, true);
    const nz = dataView.getFloat32(offset + 8, true);

    // Vertex 1
    const v1x = dataView.getFloat32(offset + 12, true);
    const v1y = dataView.getFloat32(offset + 16, true);
    const v1z = dataView.getFloat32(offset + 20, true);

    // Vertex 2
    const v2x = dataView.getFloat32(offset + 24, true);
    const v2y = dataView.getFloat32(offset + 28, true);
    const v2z = dataView.getFloat32(offset + 32, true);

    // Vertex 3
    const v3x = dataView.getFloat32(offset + 36, true);
    const v3y = dataView.getFloat32(offset + 40, true);
    const v3z = dataView.getFloat32(offset + 44, true);

    triangles.push({
      normal: [nx, ny, nz],
      v1: [v1x, v1y, v1z],
      v2: [v2x, v2y, v2z],
      v3: [v3x, v3y, v3z]
    });

    offset += 50;
  }

  return triangles;
}

function parseAsciiStl(text) {
  const triangles = [];
  const facetRegex = /facet\s+normal\s+([-\d.e+]+)\s+([-\d.e+]+)\s+([-\d.e+]+)[\s\S]*?vertex\s+([-\d.e+]+)\s+([-\d.e+]+)\s+([-\d.e+]+)[\s\S]*?vertex\s+([-\d.e+]+)\s+([-\d.e+]+)\s+([-\d.e+]+)[\s\S]*?vertex\s+([-\d.e+]+)\s+([-\d.e+]+)\s+([-\d.e+]+)/g;
  let match;

  while ((match = facetRegex.exec(text)) !== null) {
    triangles.push({
      normal: [parseFloat(match[1]), parseFloat(match[2]), parseFloat(match[3])],
      v1: [parseFloat(match[4]), parseFloat(match[5]), parseFloat(match[6])],
      v2: [parseFloat(match[7]), parseFloat(match[8]), parseFloat(match[9])],
      v3: [parseFloat(match[10]), parseFloat(match[11]), parseFloat(match[12])]
    });
  }

  return triangles;
}

// Rotates a 3D vector by angles rx, ry, rz in degrees
function rotateVector([x, y, z], rx, ry, rz) {
  const radX = (rx * Math.PI) / 180;
  const radY = (ry * Math.PI) / 180;
  const radZ = (rz * Math.PI) / 180;

  // Rx
  let y1 = y * Math.cos(radX) - z * Math.sin(radX);
  let z1 = y * Math.sin(radX) + z * Math.cos(radX);
  let x1 = x;

  // Ry
  let x2 = x1 * Math.cos(radY) + z1 * Math.sin(radY);
  let z2 = -x1 * Math.sin(radY) + z1 * Math.cos(radY);
  let y2 = y1;

  // Rz
  let x3 = x2 * Math.cos(radZ) - y2 * Math.sin(radZ);
  let y3 = x2 * Math.sin(radZ) + y2 * Math.cos(radZ);
  let z3 = z2;

  return [x3, y3, z3];
}

function triangleArea(p1, p2, p3) {
  const ab = [p2[0] - p1[0], p2[1] - p1[1], p2[2] - p1[2]];
  const ac = [p3[0] - p1[0], p3[1] - p1[1], p3[2] - p1[2]];
  const cross = [
    ab[1] * ac[2] - ab[2] * ac[1],
    ab[2] * ac[0] - ab[0] * ac[2],
    ab[0] * ac[1] - ab[1] * ac[0]
  ];
  return 0.5 * Math.sqrt(cross[0] * cross[0] + cross[1] * cross[1] + cross[2] * cross[2]);
}

// Evaluates an orientation:
// 1. Calculates the minimum Z of the rotated mesh (the print bed level).
// 2. Any face whose vertices sit right on the ground level (Z ≈ minZ) is touching the bed,
//    providing excellent adhesion and ZERO support needed.
// 3. Any face whose normal points downwards (nz < -0.3) but is ABOVE the ground (Z > minZ + eps)
//    is a true floating overhang requiring support.
function evaluateOrientation(triangles, rx, ry, rz) {
  // Pass 1: find rotated bounding box
  let minZ = Infinity, maxZ = -Infinity;
  let minX = Infinity, maxX = -Infinity;
  let minY = Infinity, maxY = -Infinity;

  const step = Math.max(1, Math.floor(triangles.length / 1500));
  const rotated = [];

  for (let i = 0; i < triangles.length; i += step) {
    const tri = triangles[i];
    const rv1 = rotateVector(tri.v1, rx, ry, rz);
    const rv2 = rotateVector(tri.v2, rx, ry, rz);
    const rv3 = rotateVector(tri.v3, rx, ry, rz);
    const rn = rotateVector(tri.normal, rx, ry, rz);

    minZ = Math.min(minZ, rv1[2], rv2[2], rv3[2]);
    maxZ = Math.max(maxZ, rv1[2], rv2[2], rv3[2]);
    minX = Math.min(minX, rv1[0], rv2[0], rv3[0]);
    maxX = Math.max(maxX, rv1[0], rv2[0], rv3[0]);
    minY = Math.min(minY, rv1[1], rv2[1], rv3[1]);
    maxY = Math.max(maxY, rv1[1], rv2[1], rv3[1]);

    rotated.push({ rv1, rv2, rv3, rn });
  }

  const modelHeight = maxZ - minZ;
  // Threshold to consider a vertex on the ground (touching build plate)
  const groundThreshold = minZ + Math.max(0.5, modelHeight * 0.015);

  let bedContactArea = 0;
  let suspendedOverhangArea = 0;

  for (const item of rotated) {
    const { rv1, rv2, rv3, rn } = item;
    const avgZ = (rv1[2] + rv2[2] + rv3[2]) / 3;
    const isGroundFacet = avgZ <= groundThreshold && rn[2] <= -0.7; // Flat face seated directly on the bed

    const area = triangleArea(rv1, rv2, rv3);

    if (isGroundFacet) {
      // Touches the ground! Excluded from overhangs and heavily rewarded for adhesion/stability
      bedContactArea += area;
    } else if (rn[2] < -0.35) {
      // Points downward but is suspended above ground -> TRUE overhang needing support
      suspendedOverhangArea += area;
    }
  }

  // Cost function to minimize:
  // - High penalty for suspended overhangs (needs supports)
  // - High reward (negative penalty) for bed contact area (flat base)
  // - Small penalty for excessive print height
  const score = (suspendedOverhangArea * 3.0) - (bedContactArea * 1.5) + (modelHeight * 0.2);

  return {
    score,
    bedContactArea,
    suspendedOverhangArea,
    modelHeight
  };
}

// Scans canonical orientations (orthogonal rotations along X, Y, Z)
export const findOptimalOrientation = async (file) => {
  const triangles = await parseStlTriangles(file);
  if (!triangles || triangles.length === 0) {
    return { rx: 0, ry: 0, rz: 0 };
  }

  const CANDIDATE_ANGLES = [
    { rx: 0, ry: 0, rz: 0 },
    { rx: 90, ry: 0, rz: 0 },
    { rx: 180, ry: 0, rz: 0 },
    { rx: 270, ry: 0, rz: 0 },
    { rx: 0, ry: 90, rz: 0 },
    { rx: 0, ry: 180, rz: 0 },
    { rx: 0, ry: 270, rz: 0 },
    { rx: 90, ry: 90, rz: 0 },
    { rx: 90, ry: 270, rz: 0 },
    { rx: 270, ry: 90, rz: 0 },
    { rx: 270, ry: 270, rz: 0 },
    { rx: 180, ry: 90, rz: 0 },
    { rx: 180, ry: 270, rz: 0 }
  ];

  let best = CANDIDATE_ANGLES[0];
  let bestScore = Infinity;

  for (const candidate of CANDIDATE_ANGLES) {
    const evalResult = evaluateOrientation(triangles, candidate.rx, candidate.ry, candidate.rz);
    if (evalResult.score < bestScore) {
      bestScore = evalResult.score;
      best = candidate;
    }
  }

  return best;
};
